-- BIRD database 'disney' translated to PostgreSQL.
-- Generated by research/advtext2sql/delivery/build.py from the live
-- benchmark server; types, keys and column comments are the server's own.

CREATE TABLE "characters" (
    "movie_title" text NOT NULL,
    "release_date" text,
    "hero" text,
    "villian" text,
    "song" text,
    PRIMARY KEY ("movie_title")
);

CREATE TABLE "director" (
    "name" text NOT NULL,
    "director" text,
    PRIMARY KEY ("name")
);

CREATE TABLE "movies_total_gross" (
    "movie_title" text NOT NULL,
    "release_date" text NOT NULL,
    "genre" text,
    "mpaa_rating" text,
    "total_gross" text,
    "inflation_adjusted_gross" text,
    PRIMARY KEY ("movie_title", "release_date")
);

CREATE TABLE "revenue" (
    "year" bigint NOT NULL,
    "Studio Entertainment[NI 1]" real,
    "Disney Consumer Products[NI 2]" real,
    "Disney Interactive[NI 3][Rev 1]" bigint,
    "Walt Disney Parks and Resorts" real,
    "Disney Media Networks" text,
    "total" bigint,
    PRIMARY KEY ("year")
);

CREATE TABLE "voice-actors" (
    "character" text NOT NULL,
    "voice-actor" text,
    "movie" text,
    PRIMARY KEY ("character")
);

